const API = '/api/v1';

function getToken() {
  try {
    const raw = localStorage.getItem('alltrue_session');
    if (!raw) return null;
    const s = JSON.parse(raw);
    return s?.access_token ?? null;
  } catch { return null; }
}

function headers() {
  const h = { 'Accept': 'application/json', 'Content-Type': 'application/json' };
  const t = getToken();
  if (t) h['Authorization'] = `Bearer ${t}`;
  return h;
}

async function json(res) {
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.message || `HTTP ${res.status}`);
  }
  return res.json();
}

export async function fetchThreads(branchId, perPage = 30) {
  const params = new URLSearchParams({ branch_id: branchId, per_page: perPage });
  const res = await fetch(`${API}/chat/threads?${params}`, { headers: headers() });
  return json(res);
}

export async function createDm(branchId, otherUserId) {
  const res = await fetch(`${API}/chat/threads/dm`, {
    method: 'POST',
    headers: headers(),
    body: JSON.stringify({ branch_id: branchId, other_user_id: otherUserId }),
  });
  return json(res);
}

export async function createGroup(branchId, name, memberIds) {
  const res = await fetch(`${API}/chat/threads/group`, {
    method: 'POST',
    headers: headers(),
    body: JSON.stringify({ branch_id: branchId, name, member_ids: memberIds }),
  });
  return json(res);
}

export async function fetchMessages(threadId, beforeId = null, limit = 40) {
  const params = new URLSearchParams({ limit });
  if (beforeId) params.set('before_id', beforeId);
  const res = await fetch(`${API}/chat/threads/${threadId}/messages?${params}`, { headers: headers() });
  return json(res);
}

export async function sendMessage(threadId, body) {
  const res = await fetch(`${API}/chat/threads/${threadId}/messages`, {
    method: 'POST',
    headers: headers(),
    body: JSON.stringify({ body }),
  });
  return json(res);
}

export async function markThreadRead(threadId, messageId = null) {
  const res = await fetch(`${API}/chat/threads/${threadId}/read`, {
    method: 'POST',
    headers: headers(),
    body: JSON.stringify(messageId ? { message_id: messageId } : {}),
  });
  return json(res);
}

export async function fetchChatUnreadCount(branchId) {
  const params = new URLSearchParams();
  if (branchId) params.set('branch_id', branchId);
  const res = await fetch(`${API}/chat/unread-count?${params}`, { headers: headers() });
  return json(res);
}

export async function fetchStaffList(branchId) {
  const params = new URLSearchParams();
  if (branchId) params.set('branch_id', branchId);
  const res = await fetch(`${API}/profiles?${params}`, { headers: headers() });
  return json(res);
}

/**
 * Chat realtime module.
 *
 * Strategy: start with polling; upgrade to WebSocket (laravel-echo + pusher-js)
 * when the soketi server is running. Falls back gracefully.
 */

let echoInstance = null;
let subscribedChannels = {};
let pollingIntervals = {};

/**
 * Try to initialize Laravel Echo. Returns true if successful.
 */
export async function initEcho() {
  try {
    const Echo = (await import('laravel-echo')).default;
    const Pusher = (await import('pusher-js')).default;
    window.Pusher = Pusher;

    echoInstance = new Echo({
      broadcaster: 'pusher',
      key: window.__ALLTRUE_WS_KEY || 'alltrue-local-key',
      wsHost: window.__ALLTRUE_WS_HOST || window.location.hostname,
      wsPort: window.__ALLTRUE_WS_PORT || 6001,
      forceTLS: false,
      disableStats: true,
      enabledTransports: ['ws'],
      authEndpoint: '/api/v1/broadcasting/auth',
      auth: {
        headers: {
          Authorization: `Bearer ${getToken()}`,
        },
      },
    });

    return true;
  } catch (e) {
    console.warn('[Chat] WebSocket init failed, using polling fallback:', e.message);
    return false;
  }
}

/**
 * Subscribe to a thread channel for new messages.
 * Falls back to polling if Echo is unavailable.
 */
export function subscribeThread(threadId, onMessage, pollFn = null) {
  if (echoInstance) {
    try {
      const channel = echoInstance.private(`chat.thread.${threadId}`);
      channel.listen('.message.created', (data) => {
        onMessage(data);
      });
      subscribedChannels[threadId] = channel;
      return;
    } catch (e) {
      console.warn('[Chat] Channel subscribe failed, falling back to poll:', e.message);
    }
  }

  if (pollFn) {
    pollingIntervals[threadId] = setInterval(pollFn, 3000);
  }
}

/**
 * Unsubscribe from a thread channel and clear polling.
 */
export function unsubscribeThread(threadId) {
  if (echoInstance && subscribedChannels[threadId]) {
    echoInstance.leave(`chat.thread.${threadId}`);
    delete subscribedChannels[threadId];
  }
  if (pollingIntervals[threadId]) {
    clearInterval(pollingIntervals[threadId]);
    delete pollingIntervals[threadId];
  }
}

/**
 * Unsubscribe all.
 */
export function unsubscribeAll() {
  Object.keys(subscribedChannels).forEach(id => unsubscribeThread(id));
  Object.keys(pollingIntervals).forEach(id => {
    clearInterval(pollingIntervals[id]);
    delete pollingIntervals[id];
  });
}

function getToken() {
  try {
    const raw = localStorage.getItem('alltrue_session');
    return raw ? JSON.parse(raw)?.access_token : null;
  } catch { return null; }
}

const API = '/api/v1';

function getToken() {
  try {
    const raw = localStorage.getItem('alltrue_session');
    if (!raw) return null;
    const s = JSON.parse(raw);
    return s?.access_token ?? null;
  } catch { return null; }
}

function headers() {
  const h = { 'Accept': 'application/json', 'Content-Type': 'application/json' };
  const t = getToken();
  if (t) h['Authorization'] = `Bearer ${t}`;
  return h;
}

async function json(res) {
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.message || `HTTP ${res.status}`);
  }
  return res.json();
}

export async function submitBugReport(data) {
  const res = await fetch(`${API}/bugs`, {
    method: 'POST',
    headers: headers(),
    body: JSON.stringify(data),
  });
  return json(res);
}

export async function fetchBugReports(branchId, filters = {}, perPage = 20) {
  const params = new URLSearchParams({ branch_id: branchId, per_page: perPage });
  if (filters.status) params.set('status', filters.status);
  if (filters.severity) params.set('severity', filters.severity);
  const res = await fetch(`${API}/bugs?${params}`, { headers: headers() });
  return json(res);
}

export async function fetchBugDetail(bugId) {
  const res = await fetch(`${API}/bugs/${bugId}`, { headers: headers() });
  return json(res);
}

export async function addBugComment(bugId, body, isInternalNote = false) {
  const res = await fetch(`${API}/bugs/${bugId}/comments`, {
    method: 'POST',
    headers: headers(),
    body: JSON.stringify({ body, is_internal_note: isInternalNote }),
  });
  return json(res);
}

export async function updateBugStatus(bugId, status, note = null) {
  const res = await fetch(`${API}/bugs/${bugId}/status`, {
    method: 'POST',
    headers: headers(),
    body: JSON.stringify({ status, note }),
  });
  return json(res);
}

export async function assignBug(bugId, assignedTo) {
  const res = await fetch(`${API}/bugs/${bugId}/assign`, {
    method: 'POST',
    headers: headers(),
    body: JSON.stringify({ assigned_to: assignedTo }),
  });
  return json(res);
}

